    &lt;button class="tw-bg-primary-500 tw-text-white tw-p-2 tw-rounded-full"&gt;
      &lt;VcIcon icon="lucide-arrow-left" /&gt;
    &lt;/button&gt;
  &lt;/template&gt;
  &lt;template #nextBtn&gt;
    &lt;button class="tw-bg-primary-500 tw-text-white tw-p-2 tw-rounded-full"&gt;
      &lt;VcIcon icon="lucide-arrow-right" /&gt;
    &lt;/button&gt;
